<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/catalog.php';require_once __DIR__.'/../lib/upload.php';
send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';$productId=trim((string)($_GET['product_id']??''));$product=vendor_product($productId,$vendorId);
if($method==='GET'){$stmt=$db->prepare('SELECT pi.id,pi.alt_text,pi.sort_order,pi.is_primary,f.id AS file_id,f.mime_type,f.size_bytes,f.scan_status,CONCAT("../files.php?id=",f.id) AS url FROM product_images pi JOIN file_assets f ON f.id=pi.file_asset_id WHERE pi.product_id=:product AND f.deleted_at IS NULL ORDER BY pi.is_primary DESC,pi.sort_order,pi.created_at');$stmt->execute(['product'=>$productId]);json_response(200,['success'=>true,'images'=>$stmt->fetchAll()]);}
if($method==='POST'){$file=$_FILES['image']??null;if(!is_array($file))json_response(422,['success'=>false,'message'=>'A product image is required.']);$count=$db->prepare('SELECT COUNT(*) FROM product_images WHERE product_id=:product');$count->execute(['product'=>$productId]);if((int)$count->fetchColumn()>=10)json_response(422,['success'=>false,'message'=>'A product can have at most 10 images.']);$asset=store_private_upload($file,'vendor',$vendorId,'product_image',['image/jpeg','image/png','image/webp'],5*1024*1024);$imageId=uuid_string();$alt=trim((string)($_POST['alt_text']??$product['name']));if(mb_strlen($alt)<3||mb_strlen($alt)>220)json_response(422,['success'=>false,'message'=>'Image alt text must be between 3 and 220 characters.']);$primary=(int)$count->fetchColumn()===0?1:(!empty($_POST['is_primary'])?1:0);$sort=max(0,min(100,(int)($_POST['sort_order']??0)));$db->beginTransaction();try{if($primary)$db->prepare('UPDATE product_images SET is_primary=0 WHERE product_id=:product')->execute(['product'=>$productId]);$db->prepare('INSERT INTO product_images (id,product_id,file_asset_id,alt_text,sort_order,is_primary,created_at) VALUES (:id,:product,:file,:alt,:sort,:primary,UTC_TIMESTAMP())')->execute(['id'=>$imageId,'product'=>$productId,'file'=>$asset['id'],'alt'=>$alt,'sort'=>$sort,'primary'=>$primary]);$db->commit();audit_event('vendor.product_image_uploaded','product',$productId,['image_id'=>$imageId]);json_response(201,['success'=>true,'message'=>'Image uploaded and queued for security scanning.','image'=>['id'=>$imageId,'file_id'=>$asset['id'],'scan_status'=>'pending']]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
if($method==='PATCH'){$body=get_json_body();$imageId=trim((string)($body['image_id']??''));$stmt=$db->prepare('SELECT pi.* FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE pi.id=:id AND p.vendor_id=:vendor LIMIT 1');$stmt->execute(['id'=>$imageId,'vendor'=>$vendorId]);if(!$stmt->fetch())json_response(404,['success'=>false,'message'=>'Image not found.']);$alt=trim((string)($body['alt_text']??''));if(mb_strlen($alt)<3||mb_strlen($alt)>220)json_response(422,['success'=>false,'message'=>'Image alt text must be between 3 and 220 characters.']);$primary=!empty($body['is_primary'])?1:0;$db->beginTransaction();try{if($primary)$db->prepare('UPDATE product_images SET is_primary=0 WHERE product_id=:product')->execute(['product'=>$productId]);$db->prepare('UPDATE product_images SET alt_text=:alt,sort_order=:sort,is_primary=:primary WHERE id=:id')->execute(['alt'=>$alt,'sort'=>max(0,min(100,(int)($body['sort_order']??0))),'primary'=>$primary,'id'=>$imageId]);$db->commit();json_response(200,['success'=>true,'message'=>'Image details updated.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
if($method==='DELETE'){$imageId=trim((string)($_GET['image_id']??''));$stmt=$db->prepare('SELECT pi.file_asset_id,f.visibility FROM product_images pi JOIN products p ON p.id=pi.product_id JOIN file_assets f ON f.id=pi.file_asset_id WHERE pi.id=:id AND p.vendor_id=:vendor LIMIT 1');$stmt->execute(['id'=>$imageId,'vendor'=>$vendorId]);$row=$stmt->fetch();if(!$row)json_response(404,['success'=>false,'message'=>'Image not found.']);if($row['visibility']==='public')json_response(409,['success'=>false,'message'=>'A published image cannot be removed directly. Upload replacements and submit the product for review.']);$db->beginTransaction();try{$db->prepare('DELETE FROM product_images WHERE id=:id')->execute(['id'=>$imageId]);$db->prepare('UPDATE file_assets SET deleted_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$row['file_asset_id']]);$db->commit();audit_event('vendor.product_image_deleted','product',$productId,['image_id'=>$imageId]);json_response(200,['success'=>true,'message'=>'Image removed.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
